SELECT idt.id, idt.filing_no, idt.`STATUS`, idt.erp_status, idt.wbs_project, idt.wbs_element, idt.use_keep_dept, idt.entity_keep_dept, idt.create_time, idt.process_status, idt.owner_unit, idt.owner_unit_name, idt.property_dept, idt.property_dept_name FROM idevelop_device_transfer idt LEFT JOIN idevelop_device_transfer_detail idtd ON idt.id = idtd.transfer_id
idt.is_deleted = 0
AND idtd.device_code LIKE CONCAT('%', #{deviceTransferDTO.deviceCode}, '%')
AND idtd.device_category = #{deviceTransferDTO.deviceCategory}
AND idtd.device_type = #{deviceTransferDTO.deviceType}
AND idt.region_code LIKE CONCAT(#{deviceTransferDTO.regionCode}, '%')
AND idt.owner_unit = #{deviceTransferDTO.ownerUnit}
AND idt.property_dept = #{deviceTransferDTO.propertyDept}
AND idt.wbs_project = #{deviceTransferDTO.wbsProject}
AND idt.create_time >= #{deviceTransferDTO.minDate} AND idt.create_time <= #{deviceTransferDTO.maxDate}
GROUP BY idt.id ORDER BY idt.create_time DESC

SELECT idt.id, idt.device_type, idt.device_category, idt.receiver_time, idt.receiver, idt.filing_no, idt.`STATUS`, idt.erp_status, idt.wbs_project, idt.wbs_element, iu.real_name, idt.use_keep_dept, idt.entity_keep_dept, idt.create_time, idt.process_status, idt.owner_unit, idt.property_dept, idt.owner_unit_name, idt.property_dept_name FROM idevelop_device_transfer idt LEFT JOIN idevelop_user iu ON idt.receiver = iu.id
idt.is_deleted = 0
and region_code = #{dto.regionCode}
AND filing_no IN
#{item}
ORDER BY idt.create_time DESC
